/** Technology as written in `projects.ts` → its mark. */
const BY_TECHNOLOGY: Record<string, keyof typeof MARKS> = {
	SvelteKit: 'svelte',
	'SvelteKit server': 'svelte',
	TypeScript: 'typescript',
	NestJS: 'nestjs',
	PostgreSQL: 'postgresql',
	Redis: 'redis',
	Prisma: 'prisma',
	Fastify: 'fastify',
	'Socket.IO': 'socketdotio',
	Swift: 'swift',
	SwiftUI: 'swift',
	Kotlin: 'kotlin',
	'Jetpack Compose': 'jetpackcompose',
	Compose: 'jetpackcompose',
	'Tailwind CSS': 'tailwindcss',
	SQLite: 'sqlite',
	Mapbox: 'mapbox',
	'Git worktrees': 'git',
	'SAML/OIDC': 'openid',
	SSO: 'openid',
	'Drizzle ORM': 'drizzle',
	Passport: 'passport',
	'JSON Web Tokens': 'jsonwebtokens',
	Swagger: 'swagger',
	'Chart.js': 'chartdotjs',
	D3: 'd3',
	'Google Calendar': 'googlecalendar',
	Vitest: 'vitest',
	Lucide: 'lucide',
	TypeORM: 'typeorm',
	Resend: 'resend',
	TanStack: 'tanstack',
	GSAP: 'gsap',
	Zod: 'zod',
	Pino: 'pino',
	Puppeteer: 'puppeteer',
	Anthropic: 'anthropic',
	Xcode: 'xcode',
	macOS: 'macos',
	Android: 'android',
	'Android Studio': 'androidstudio',
	sharp: 'sharp',
	'React PDF': 'react',
	Vercel: 'vercel',
	WebSockets: 'websockets',
	BullMQ: 'bullmq',
	'Azure Blob': 'azureblob',
	'Azure AI': 'azureai',
	'Amazon S3': 'amazons3',
	PDF: 'pdf',
	jsPDF: 'pdf',
	pdfmake: 'pdf',
	AVIF: 'avif'
};

/** The mark for a technology, when one exists. Concepts have none on purpose. */
export function techMark(technology: string): TechMark | undefined {
	const key = BY_TECHNOLOGY[technology.trim()];
	return key ? MARKS[key] : undefined;
}

/** Two letters standing in for a technology that has no brand mark. */
export function techMonogram(technology: string): string {
	const words = technology
		.trim()
		.split(/[\s·/]+/)
		.filter(Boolean);
	if (words.length > 1) return (words[0][0] + words[1][0]).toUpperCase();
	return technology.trim().slice(0, 2).toUpperCase();
}
